      + (emp ? '' : `<div class="kpis">${[{ label: 'Jobs in progress', icon: 'hardhat', value: act.length, count: act.length }, { label: 'Contract value in progress', icon: 'dollar', value: T.money(T.sum(act, (j) => j.value)), roles: ['owner', 'manager'] }, { label: 'Behind schedule', icon: 'alert', value: act.filter((j) => j.behind).length, delta: '<span class="faint">waiting on materials</span>' }, { label: 'Starting in 30 days', icon: 'calendar', value: groups.upcoming.length }].filter((k) => T.can(k.roles)).map(ui.kpi).join('')}</div>`)
