    return ui.pageHead({ title: 'Permits and inspections', sub: 'Every permit, inspection date and correction in one tracker', actions: `<button class="btn btn-primary" data-act="newPermit">${icon('plus', 'sm')}Add permit</button>` })
      + `<div class="kpis">${[{ label: 'Inspections this week', icon: 'calendar', value: P.filter((p) => p.status === 'Inspection scheduled' && T.dayDiff(p.date) <= 7).length }, { label: 'Waiting on the town', icon: 'hourglass', value: P.filter((p) => p.status === 'Applied').length }, { label: 'Corrections needed', icon: 'alert', value: P.filter((p) => p.status === 'Corrections').length }, { label: 'Passed this month', icon: 'check', value: P.filter((p) => p.status === 'Passed').length }].map(ui.kpi).join('')}</div>`
      + ui.card({ flush: true, body: ui.table({ cols: [{ l: 'Permit or inspection', v: (p) => `<b>${esc(p.type)}</b><div class="tiny faint">${esc(p.num)} · ${esc(p.muni)}</div>` }, { l: 'Job', v: (p) => `<a href="#/jobs/${p.jobId}">${esc(job(p.jobId).client)}</a><div class="tiny faint">${esc(job(p.jobId).addr.split(',')[0])}</div>` }, { l: 'Date', v: (p) => T.relDay(p.date) }, { l: 'Status', v: (p) => ui.badge(p.status, PERMIT_TONE[p.status], true) + (p.note ? `<div class="tiny down" style="margin-top:3px">${esc(p.note)}</div>` : '') }, { l: '', r: 1, v: (p) => p.status === 'Inspection scheduled' ? `<button class="btn btn-xs btn-success" data-act="permitPass" data-id="${p.id}">Passed</button>` : p.status === 'Approved' || p.status === 'Corrections' ? `<button class="btn btn-xs" data-act="permitSched" data-id="${p.id}">Schedule inspection</button>` : '' }], rows: P }) });
